-- PB Bilibili 162 Cup I 2026 — seeded production schema
create table if not exists public.seeded_tournaments (id bigint generated by default as identity primary key,name text not null,organizer text,event_start date,event_end date,venue text,registration_fee numeric,registration_deadline text,technical_meeting text,match_system text,contact_registration text,email_website text,raw_information jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.seeded_players (id bigint generated by default as identity primary key,tournament_id bigint references public.seeded_tournaments(id) on delete cascade,source_sheet text not null,source_no integer,player_name text not null,club_name text,seeded_quality text,division_level text,tournament_qualification text,region_status text,validity_status text,archive_category text,gender text,eligible_category text,normalized_name text generated always as (regexp_replace(lower(trim(player_name)), '[^a-z0-9]+', ' ', 'g')) stored,raw_data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.seeded_mapping_rules (id bigint generated by default as identity primary key,tournament_id bigint references public.seeded_tournaments(id) on delete cascade,rule_code text not null,rule_name text not null,priority integer not null default 100,description text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.seeded_pair_evaluations (id bigint generated by default as identity primary key,tournament_id bigint references public.seeded_tournaments(id) on delete cascade,registration_id bigint,player1_seeded_id bigint references public.seeded_players(id),player2_seeded_id bigint references public.seeded_players(id),category text,score numeric,risk_level text,eligible boolean,reasons jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create table if not exists public.seeded_draw_assignments (id bigint generated by default as identity primary key,tournament_id bigint references public.seeded_tournaments(id) on delete cascade,registration_id bigint,category text not null,seed_number integer,draw_slot integer,fairness_score numeric,mapping_status text not null default 'proposed',notes text,created_at timestamptz not null default now());
create index if not exists idx_seeded_players_tournament on public.seeded_players(tournament_id);
create index if not exists idx_seeded_players_quality on public.seeded_players(seeded_quality);
create index if not exists idx_seeded_players_name on public.seeded_players(normalized_name);
create index if not exists idx_seeded_players_club on public.seeded_players(club_name);
create index if not exists idx_seeded_mapping_rules_tournament on public.seeded_mapping_rules(tournament_id);
create index if not exists idx_seeded_pair_evaluations_tournament on public.seeded_pair_evaluations(tournament_id);
create index if not exists idx_seeded_draw_assignments_tournament on public.seeded_draw_assignments(tournament_id);
